func BenchmarkPopulationLegacyColocatedPlanGuardV1(b *testing.B) {
	ctx := context.Background()
	raw := []byte(populationLegacyColocatedPlanGuardJSONV1)
	// Decode and independently validate the authentic frozen ledger before any
	// subbenchmark timer. Both calls use APIs present at the predecessor.
	plan, err := DecodeColocatedAuditPlanV1(ctx, bytes.NewReader(raw))
	if err != nil {
		b.Fatalf("legacy fixture decode: %v", err)
	}
	if err := ValidateColocatedAuditPlanV1(ctx, plan); err != nil {
		b.Fatalf("legacy fixture validation: %v", err)
	}
	if len(plan.Writes) != 6 || len(plan.Final) != 4 {
		b.Fatal("legacy fixture lost its six-outcome/four-ID scope")
	}
	b.Run("validate", func(b *testing.B) {
		b.ReportAllocs()
		b.ResetTimer()
		for i := 0; i < b.N; i++ {
			if err := ValidateColocatedAuditPlanV1(ctx, plan); err != nil {
				b.Fatal(err)
			}
		}
	})
	b.Run("decode", func(b *testing.B) {
		b.ReportAllocs()
		b.ResetTimer()
		for i := 0; i < b.N; i++ {
			if _, err := DecodeColocatedAuditPlanV1(ctx, bytes.NewReader(raw)); err != nil {
				b.Fatal(err)
			}
		}
	})
}
